class Solution {
public:
    vector<string> spellchecker(vector<string>& wordlist, vector<string>& queries) {
        unordered_set<string> exact(wordlist.begin(), wordlist.end());
        unordered_map<string, string> cap_map, vowel_map;
        auto to_lower = [](string s) {
            for (char& c : s) c = tolower(c);
            return s;
        };
        auto devowel = [&](string s) {
            s = to_lower(s);
            for (char& c : s) {
                if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') c = '*';
            }
            return s;
        };
        for (const string& w : wordlist) {
            string low = to_lower(w);
            if (!cap_map.count(low)) cap_map[low] = w;
            string dev = devowel(w);
            if (!vowel_map.count(dev)) vowel_map[dev] = w;
        }
        vector<string> res;
        for (const string& q : queries) {
            if (exact.count(q)) {
                res.push_back(q);
            } else {
                string low = to_lower(q);
                if (cap_map.count(low)) {
                    res.push_back(cap_map[low]);
                } else {
                    string dev = devowel(q);
                    if (vowel_map.count(dev)) {
                        res.push_back(vowel_map[dev]);
                    } else {
                        res.push_back("");
                    }
                }
            }
        }
        return res;
    }
};

class Solution {
    private String devowel(String w) {
        StringBuilder sb = new StringBuilder();
        for (char c : w.toLowerCase().toCharArray()) {
            if ("aeiou".indexOf(c) >= 0) sb.append('*');
            else sb.append(c);
        }
        return sb.toString();
    }
    public String[] spellchecker(String[] wordlist, String[] queries) {
        Set<String> exact = new HashSet<>(Arrays.asList(wordlist));
        Map<String, String> capMap = new HashMap<>();
        Map<String, String> vowelMap = new HashMap<>();
        for (String w : wordlist) {
            String lower = w.toLowerCase();
            capMap.putIfAbsent(lower, w);
            vowelMap.putIfAbsent(devowel(w), w);
        }
        String[] res = new String[queries.length];
        for (int i = 0; i < queries.length; i++) {
            String q = queries[i];
            if (exact.contains(q)) {
                res[i] = q;
            } else if (capMap.containsKey(q.toLowerCase())) {
                res[i] = capMap.get(q.toLowerCase());
            } else if (vowelMap.containsKey(devowel(q))) {
                res[i] = vowelMap.get(devowel(q));
            } else {
                res[i] = "";
            }
        }
        return res;
    }
}

var spellchecker = function(wordlist, queries) {
    const exact = new Set(wordlist);
    const capMap = new Map();
    const vowelMap = new Map();
    const devowel = (w) => w.toLowerCase().replace(/[aeiou]/g, '*');
    for (const w of wordlist) {
        const lower = w.toLowerCase();
        if (!capMap.has(lower)) capMap.set(lower, w);
        const dev = devowel(w);
        if (!vowelMap.has(dev)) vowelMap.set(dev, w);
    }
    return queries.map(q => {
        if (exact.has(q)) return q;
        const lower = q.toLowerCase();
        if (capMap.has(lower)) return capMap.get(lower);
        const dev = devowel(q);
        if (vowelMap.has(dev)) return vowelMap.get(dev);
        return "";
    });
};
